CREATE TABLE customers(id varchar(128) PRIMARY KEY,display_name varchar(255) NOT NULL,status varchar(16) NOT NULL CHECK(status IN ('ACTIVE','BLOCKED')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE accounts(id varchar(128) PRIMARY KEY,customer_id varchar(128) NOT NULL REFERENCES customers(id) ON DELETE RESTRICT,currency char(3) NOT NULL CHECK(currency='JOD'),available_balance numeric(19,3) NOT NULL CHECK(available_balance>=0),opening_balance numeric(19,3) NOT NULL CHECK(opening_balance>=0),status varchar(16) NOT NULL CHECK(status IN ('ACTIVE','FROZEN','CLOSED')),receive_enabled boolean NOT NULL DEFAULT true,transfer_limit numeric(19,3) NOT NULL DEFAULT 10000.000 CHECK(transfer_limit>0),version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE debit_grants(account_id varchar(128) REFERENCES accounts(id) ON DELETE RESTRICT,principal varchar(128) NOT NULL,PRIMARY KEY(account_id,principal));
CREATE TABLE recipient_restrictions(account_id varchar(128) REFERENCES accounts(id) ON DELETE RESTRICT,allowed_customer_id varchar(128) REFERENCES customers(id) ON DELETE RESTRICT,PRIMARY KEY(account_id,allowed_customer_id));
-- Account identifiers intentionally have no foreign key here so rejected unknown-account instructions can be audited.
CREATE TABLE payments(payment_id uuid PRIMARY KEY,from_account_id varchar(128) NOT NULL,to_account_id varchar(128) NOT NULL,amount numeric(19,3) NOT NULL CHECK(amount>0),currency char(3) NOT NULL DEFAULT 'JOD' CHECK(currency='JOD'),instruction_date timestamptz NOT NULL,purpose varchar(255) NOT NULL,notes varchar(1000),payload_fingerprint char(64) NOT NULL,status varchar(16) CHECK(status IN('COMPLETED','REJECTED')),rejection_code varchar(64),rejection_http integer,created_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,requested_by varchar(128) NOT NULL,correlation_id uuid NOT NULL,CHECK(from_account_id<>to_account_id));
CREATE INDEX payment_from_date ON payments(from_account_id,created_at);CREATE INDEX payment_to_date ON payments(to_account_id,created_at);
CREATE TABLE ledger_entries(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,payment_id uuid NOT NULL REFERENCES payments(payment_id) ON DELETE RESTRICT,account_id varchar(128) NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,entry_type varchar(6) NOT NULL CHECK(entry_type IN('DEBIT','CREDIT')),signed_amount numeric(19,3) NOT NULL,balance_after numeric(19,3) NOT NULL CHECK(balance_after>=0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(payment_id,entry_type),CHECK((entry_type='DEBIT' AND signed_amount<0) OR(entry_type='CREDIT' AND signed_amount>0)));
CREATE INDEX ledger_account ON ledger_entries(account_id);
CREATE FUNCTION prohibit_financial_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Financial records are immutable'; END $$;
CREATE TRIGGER immutable_ledger BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION prohibit_financial_mutation();
CREATE FUNCTION protect_payment() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' OR OLD.status IS NOT NULL THEN RAISE EXCEPTION 'Payment is immutable'; END IF;RETURN NEW;END $$;
CREATE TRIGGER immutable_payment BEFORE UPDATE OR DELETE ON payments FOR EACH ROW EXECUTE FUNCTION protect_payment();
CREATE FUNCTION verify_payment() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE p payments; n bigint;total numeric;BEGIN SELECT * INTO p FROM payments WHERE payment_id=NEW.payment_id;SELECT count(*),coalesce(sum(signed_amount),0) INTO n,total FROM ledger_entries WHERE payment_id=p.payment_id;IF p.status IS NULL OR(p.status='COMPLETED' AND(n<>2 OR total<>0)) OR(p.status='REJECTED' AND n<>0) THEN RAISE EXCEPTION 'Unbalanced or unfinished payment';END IF;IF p.status='COMPLETED' AND EXISTS(SELECT 1 FROM ledger_entries e WHERE e.payment_id=p.payment_id AND ((e.entry_type='DEBIT' AND(e.account_id<>p.from_account_id OR e.signed_amount<>-p.amount)) OR(e.entry_type='CREDIT' AND(e.account_id<>p.to_account_id OR e.signed_amount<>p.amount)))) THEN RAISE EXCEPTION 'Ledger does not match payment';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER balanced_payment AFTER INSERT OR UPDATE ON payments DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION verify_payment();
CREATE CONSTRAINT TRIGGER balanced_ledger AFTER INSERT ON ledger_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION verify_payment();
CREATE TABLE rate_limits(principal varchar(255) NOT NULL,window_start timestamptz NOT NULL,requests integer NOT NULL,PRIMARY KEY(principal,window_start));
